import torch
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA source implementing max‑reduction over an arbitrary dimension.
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

template <typename scalar_t>
__global__ void max_reduce_kernel(const scalar_t* __restrict__ input,
                                  scalar_t* __restrict__ output,
                                  int64_t outer_size,
                                  int64_t reduce_size,
                                  int64_t inner_size) {
    // One thread per output element (outer * inner)
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = outer_size * inner_size;
    if (idx >= total) return;

    int64_t outer_idx = idx / inner_size;   // index in outer dimensions
    int64_t inner_idx = idx % inner_size;   // index in inner dimensions

    // stride to the first element of the reduction slice
    const scalar_t* slice = input + outer_idx * reduce_size * inner_size + inner_idx;

    // perform reduction
    scalar_t best = slice[0];
    #pragma unroll
    for (int64_t r = 1; r < reduce_size; ++r) {
        scalar_t cur = slice[r * inner_size];
        if (cur > best) best = cur;
    }
    output[idx] = best;
}

// ------------------------------------------------------------------
// C++ wrapper called from Python
// ------------------------------------------------------------------
torch::Tensor max_reduce_forward(torch::Tensor input, int64_t dim) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.scalar_type() == torch::kHalf, "only fp16 supported");
    TORCH_CHECK(dim >= 0 && dim < input.dim(), "invalid reduction dimension");

    auto in_sizes = input.sizes();

    int64_t reduce_size = in_sizes[dim];
    int64_t outer_size = 1;
    for (int i = 0; i < dim; ++i) outer_size *= in_sizes[i];
    int64_t inner_size = 1;
    for (int i = dim + 1; i < input.dim(); ++i) inner_size *= in_sizes[i];

    // compute output shape (input shape with `dim` removed)
    std::vector<int64_t> out_sizes;
    out_sizes.reserve(input.dim() - 1);
    for (int i = 0; i < input.dim(); ++i) {
        if (i != dim) out_sizes.push_back(in_sizes[i]);
    }
    auto output = torch::empty(out_sizes, input.options());

    const int threads = 256;
    const int blocks = static_cast<int>((outer_size * inner_size + threads - 1) / threads);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "max_reduce_forward", ([&] {
        max_reduce_kernel<scalar_t><<<blocks, threads>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            outer_size,
            reduce_size,
            inner_size);
    }));
    cudaGetLastError(); // launch check
    return output;
}

// ------------------------------------------------------------------
// PyBind11 binding
// ------------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("max_reduce_forward", &max_reduce_forward, "Max reduction (fp16)");
}
'''

# ------------------------------------------------------------------
# Build the extension (the harness will supply appropriate flags)
# ------------------------------------------------------------------
max_reduce = load_inline(name='max_reduce',
                         cpp_sources='',
                         cuda_sources=cuda_source,
                         functions=['max_reduce_forward'],
                         verbose=False)

# ------------------------------------------------------------------
# ModelNew: drop‑in replacement for the reference Model
# ------------------------------------------------------------------
class ModelNew(torch.nn.Module):
    """
    Model that performs a max‑reduction over a user‑specified dimension
    using a custom CUDA kernel. All tensors are fp16.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew only supports CUDA tensors")
        if x.dtype != torch.float16:
            raise RuntimeError("ModelNew only supports fp16 tensors")
        return max_reduce.max_reduce_forward(x, self.dim)

# ------------------------------------------------------------------
# Helper functions matching the reference script
# ------------------------------------------------------------------
def get_inputs():
    batch_size = 128
    dim1 = 4096
    dim2 = 4095
    x = torch.rand(batch_size, dim1, dim2, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    # Example: reduce over dimension 1 (as in the reference)
    return [1]

# ------------------------------------------------------------------
# Example usage (for local testing only; remove when integrating)
# ------------------------------------------------------------------
if __name__ == "__main__":
    dim = 1
    model = ModelNew(dim).cuda()
    x = torch.rand(128, 4096, 4095, dtype=torch.float16, device='cuda')
    out = model(x)
    # sanity check against torch.max
    ref = torch.max(x, dim=dim)[0]
    print(torch.allclose(out, ref, atol=1e-3, rtol=1e-3))
